class Handler(SimpleHTTPRequestHandler):
    def __init__(self,*args,**kwargs):super().__init__(*args,directory=str(ROOT),**kwargs)
    def log_message(self,*args):pass
    def list_directory(self,path):self.send_error(403);return None
    def do_GET(self):
        if self.headers.get('Host') not in {'127.0.0.1:8772','localhost:8772'}:self.send_error(403);return
        path=urlsplit(self.path).path
        if path!='/':
            candidate=(ROOT/path.lstrip('/')).resolve()
            if not candidate.is_relative_to(ROOT.resolve()) or candidate.suffix not in {'.html','.css','.js','.png','.svg','.json'}:
                self.send_error(404);return
        super().do_GET()
    def end_headers(self):
        self.send_header('Cache-Control','no-store')
        self.send_header('X-Content-Type-Options','nosniff')
        self.send_header('Referrer-Policy','no-referrer')
        self.send_header('Content-Security-Policy',"default-src 'self'; img-src 'self' data:; style-src 'self'; script-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'")
        super().end_headers()


def build_assets():
    ROOT.mkdir(exist_ok=True)
    (ROOT/'index.html').write_text(HTML,encoding='utf-8')
    (ROOT/'report.css').write_text(CSS+'\n.path-precision{grid-column:1/-1;font-size:12px;color:#52677d;margin:2px 0 0;line-height:1.9}',encoding='utf-8')
    (ROOT/'report.js').write_text(ROOT.with_name('comparison_report.js').read_text(encoding='utf-8'),encoding='utf-8')
    if not (ROOT/'reviews.json').exists():(ROOT/'reviews.json').write_text(json.dumps({'title':'المقارنة قيد القياس','text':'سنوازن بين حفظ الملامح وكلفة التنفيذ بعد اكتمال العينات.','recommendations':[],'rows':{}},ensure_ascii=False),encoding='utf-8')


if __name__=='__main__':
    build_assets()
    print('Comparison report: http://127.0.0.1:8772/',flush=True)
    ThreadingHTTPServer(('127.0.0.1',8772),Handler).serve_forever()
